// Collect All Sections | Mode: Run Once for All Items
// Gathers everything the final report needs into ONE item.
// The section HTML comes from Check Sections (already cleaned, with a visible placeholder for any section that failed).
// The images come from Encode to Base and are matched to the trend segments the same way Collect Report Data matches them.
// Social post images are NOT included: they are third-party photos and the report says images were not analysed.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const key = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');

const checked = safe(() => $('Check Sections').first().json, {}) || {};
const collected = safe(() => $('Collect Report Data').first().json.report, {}) || {};

const DEFAULT_ORDER = ['executive_summary', 'scope', 'market_research', 'category', 'attributes', 'visual_trends', 'risks', 'recommendations'];
const order = arr(checked.section_order).length ? arr(checked.section_order) : DEFAULT_ORDER;
const sections = checked.report_sections && typeof checked.report_sections === 'object' ? checked.report_sections : {};

// images: one per trend segment, matched by name first and by position second; only valid base64 is kept
const segments = arr(collected.segments);
const encoded = safe(() => $('Encode to Base').all().map((i) => i.json), []);
const images = segments.map((s, idx) => {
  const match = encoded.find((e) => key(e.segmentName) === key(s.name)) || (encoded.length === segments.length ? encoded[idx] : null);
  const b64 = match && match.hasImage ? String(match.base64Image || '').replace(/\s+/g, '') : '';
  const valid = b64.length > 20 && /^[A-Za-z0-9+/]+={0,2}$/.test(b64);
  const mime = match && /^image\/(jpeg|png|webp)$/.test(String(match.mimeType)) ? match.mimeType : 'image/jpeg';
  return { n: s.n, name: String(s.name || ''), mimeType: valid ? mime : null, base64: valid ? b64 : null };
});

// date: the day the sections were generated (UTC), formatted for people
const iso = /^\d{4}-\d{2}-\d{2}$/.test(String(checked.generated_on)) ? checked.generated_on : new Date().toISOString().slice(0, 10);
const date = new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });

return [{
  json: {
    sections,
    order,
    status: checked.section_status || {},
    notes: checked.section_notes || {},
    failed: arr(checked.failed_sections),
    review: arr(checked.sections_needing_review),
    ready: checked.ready === true,
    imagePlan: arr(checked.image_plan),
    dataWarnings: arr(checked.data_warnings),
    images,
    metadata: { category: String(checked.category || collected.category || 'Rug'), date, isoDate: iso },
  },
}];

// Assemble HTML Report | Mode: Run Once for All Items
// Builds ONE self-contained HTML page: no external fonts, scripts or links, so it opens offline and cannot call out.
//  - sections are put in the order Check Sections gave, each in its own <section>
//  - [[IMAGE_n]] tokens in the Visual Trend Story become embedded images (with the real image type); an image whose token
//    the model forgot is added to the end of that section, so no illustration is lost
//  - a banner at the top says so when a section failed or needs review: the report never hides a gap
//  - everything inserted from data is escaped
const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sections = d.sections || {};
const order = Array.isArray(d.order) ? d.order : [];
const images = Array.isArray(d.images) ? d.images : [];
const meta = d.metadata || {};
const category = meta.category || 'Rug';
const date = meta.date || '';

const TITLES = {
  executive_summary: 'Executive Summary', scope: 'Scope of Research', market_research: 'Market and Customer Insights',
  category: 'Category Deep Dive and Sizing', attributes: 'Attribute and Assortment Analysis', visual_trends: 'Visual Trend Story',
  risks: 'Risks and Watchouts', recommendations: 'Demand Signals and Recommendations',
};

// defence in depth: Check Sections already removed these, but the page must never carry them
const clean = (h) => String(h ?? '')
  .replace(/```[a-z]*\s*/gi, '')
  .replace(/<(script|style|iframe|object|embed|link|meta|base|form)\b[\s\S]*?(<\/\1\s*>|$)/gi, '')
  .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
  .replace(/javascript:/gi, '')
  .trim();

const figure = (img) => `<figure class="moodboard"><img src="data:${img.mimeType};base64,${img.base64}" alt="AI-generated illustration of the ${esc(img.name)} style"><figcaption>${esc(img.name)}: AI-generated illustration of the style, not a product photo</figcaption></figure>`;
const byN = new Map(images.map((i) => [Number(i.n), i]));
const used = new Set();

const renderSection = (k) => {
  let h = clean(sections[k]);
  if (k === 'visual_trends') {
    h = h.replace(/<p>\s*\[\[IMAGE_(\d+)\]\]\s*<\/p>|\[\[IMAGE_(\d+)\]\]/g, (m, a, b) => {
      const n = Number(a || b);
      const img = byN.get(n);
      if (!img || !img.base64 || used.has(n)) return '';
      used.add(n);
      return figure(img);
    });
    // illustrations whose token the model left out: add them, so the report always shows every image it has
    const left = images.filter((i) => i.base64 && !used.has(Number(i.n)));
    if (left.length) {
      left.forEach((i) => used.add(Number(i.n)));
      h += `<h3>Illustrations</h3><div class="gallery">${left.map(figure).join('')}</div>`;
    }
  }
  h = h.replace(/\[\[IMAGE_\d+\]\]/g, '');
  return `<section id="${esc(k)}">${h}</section>`;
};

const body = order.filter((k) => typeof sections[k] === 'string' && sections[k].trim()).map(renderSection).join('\n');

// banner: sections that failed or need review are named at the top of the report
const failed = Array.isArray(d.failed) ? d.failed : [];
const review = Array.isArray(d.review) ? d.review : [];
const name = (k) => esc(TITLES[k] || k);
const banner = failed.length || review.length
  ? `<div class="banner"><strong>Incomplete report.</strong> ${failed.length ? `Not generated: ${failed.map(name).join(', ')}. ` : ''}${review.length ? `Needs review before use: ${review.map(name).join(', ')}.` : ''}</div>`
  : '';

const CSS = [
  ':root { --primary:#7C3AED; --primary-light:#A78BFA; --secondary:#1F2937; --bg:#F9FAFB; --card:#FFFFFF; --border:#E5E7EB; --text:#1F2937; --muted:#6B7280; --warn:#92400E; --warn-bg:#FEF3C7; }',
  '* { margin:0; padding:0; box-sizing:border-box; }',
  'body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; font-size:14px; line-height:1.6; color:var(--text); background:var(--bg); }',
  '.report-container { max-width:1000px; margin:0 auto; padding:40px 24px; }',
  '.report-header { background:linear-gradient(135deg,var(--primary) 0%,#5B21B6 100%); color:#fff; padding:44px 40px; border-radius:16px; margin-bottom:24px; }',
  '.report-header h1 { font-size:30px; font-weight:700; margin-bottom:8px; }',
  '.report-header .subtitle { font-size:16px; opacity:.9; }',
  '.report-header .meta { margin-top:14px; font-size:13px; opacity:.85; }',
  '.banner { background:var(--warn-bg); color:var(--warn); border-left:4px solid #F59E0B; border-radius:8px; padding:14px 18px; margin-bottom:24px; }',
  'section { background:var(--card); border-radius:12px; padding:32px; margin-bottom:24px; box-shadow:0 1px 3px rgba(0,0,0,.1); }',
  'section h2 { font-size:22px; font-weight:600; margin-bottom:20px; padding-bottom:12px; border-bottom:2px solid var(--primary-light); }',
  'section h3 { font-size:16px; font-weight:600; color:var(--primary); margin:22px 0 10px 0; }',
  'p { margin-bottom:12px; }',
  'ul, ol { margin:0 0 14px 22px; }',
  'li { margin-bottom:6px; }',
  'table { width:100%; border-collapse:collapse; margin:14px 0 18px 0; font-size:13px; }',
  'th, td { border:1px solid var(--border); padding:8px 10px; text-align:left; vertical-align:top; }',
  'th { background:#F3F4F6; font-weight:600; }',
  'tbody tr:nth-child(even) td { background:#FAFAFA; }',
  'figure.moodboard { margin:18px 0; border:1px solid var(--border); border-radius:12px; overflow:hidden; background:var(--bg); }',
  'figure.moodboard img { display:block; width:100%; height:auto; max-height:520px; object-fit:cover; }',
  'figure.moodboard figcaption { padding:10px 14px; font-size:12px; color:var(--muted); }',
  '.gallery { display:grid; grid-template-columns:repeat(auto-fit,minmax(260px,1fr)); gap:16px; }',
  '.report-footer { text-align:center; padding:28px; color:var(--muted); font-size:12px; }',
  '@media (max-width:768px) { .report-header { padding:28px 20px; } .report-header h1 { font-size:22px; } section { padding:20px; } table { display:block; overflow-x:auto; } }',
  '@media print { body { background:#fff; } section { box-shadow:none; break-inside:avoid-page; } }',
].join('\n');

const html = '<!DOCTYPE html>' +
  '<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">' +
  `<title>${esc(category)} Trend Report</title><style>${CSS}</style></head><body><div class="report-container">` +
  `<header class="report-header"><h1>${esc(category)} Trend Report</h1><p class="subtitle">Market Intelligence and Trend Analysis</p>` +
  `<p class="meta">Generated: ${esc(date)} | Retail Market Trend Discovery workflow</p></header>` +
  banner +
  `<main>${body}</main>` +
  `<footer class="report-footer"><p>Counts, shares and prices are computed by the workflow. Text sections were written by an AI model from the sources listed in the Scope of Research. Illustrations are AI-generated.</p><p>${esc(date)}</p></footer>` +
  '</div></body></html>';

return [{ json: { cleanedHtml: html, imagesPlaced: used.size } }];

// Section Validator1 | Mode: Run Once for All Items
// Checks the finished page against what Check Sections reported and what the page really contains.
// isValid is true only when every section is present and was generated, no image token is left,
// every image that existed was embedded, and the page is complete.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const input = $input.first().json;
const html = String(input.cleanedHtml || '');
const info = safe(() => $('Collect All Sections').first().json, {}) || {};

const REQUIRED = [
  ['executive_summary', 'Executive Summary'], ['scope', 'Scope of Research'], ['market_research', 'Market and Customer Insights'],
  ['category', 'Category Deep Dive and Sizing'], ['attributes', 'Attribute and Assortment Analysis'], ['visual_trends', 'Visual Trend Story'],
  ['risks', 'Risks and Watchouts'], ['recommendations', 'Demand Signals and Recommendations'],
];
const PLACEHOLDER = /could not be generated automatically|could not be built/i;
const validation = { isValid: true, sectionsFound: [], sectionsMissing: [], sectionsFailed: [], sectionsNeedingReview: arr(info.review), imageCount: 0, expectedImages: 0, warnings: [] };

for (const [k, title] of REQUIRED) {
  const m = html.match(new RegExp(`<section id="${k}">([\\s\\S]*?)</section>`));
  if (!m) { validation.sectionsMissing.push(title); continue; }
  if (PLACEHOLDER.test(m[1])) validation.sectionsFailed.push(title); else validation.sectionsFound.push(title);
}
validation.imageCount = (html.match(/<img\s[^>]*src="data:image\/(?:jpeg|png|webp);base64,/g) || []).length;
validation.expectedImages = arr(info.images).filter((i) => i && i.base64).length;

if (validation.sectionsMissing.length) validation.warnings.push(`Missing sections: ${validation.sectionsMissing.join(', ')}`);
if (validation.sectionsFailed.length) validation.warnings.push(`Sections that could not be generated: ${validation.sectionsFailed.join(', ')}`);
if (validation.sectionsNeedingReview.length) validation.warnings.push(`Sections that need review: ${validation.sectionsNeedingReview.join(', ')}`);
if (validation.expectedImages === 0) validation.warnings.push('No images were available to embed');
else if (validation.imageCount < validation.expectedImages) validation.warnings.push(`Only ${validation.imageCount} of ${validation.expectedImages} images were embedded`);
if (/\[\[IMAGE_\d+\]\]/.test(html)) validation.warnings.push('An image placeholder was left in the text');
if (/<script\b/i.test(html)) validation.warnings.push('The page contains a script tag');
if (!/<\/html>\s*$/.test(html.trim())) validation.warnings.push('The HTML looks cut off');
if (html.length > 15 * 1024 * 1024) validation.warnings.push('The page is larger than 15 MB');

validation.isValid = !validation.sectionsMissing.length && !validation.sectionsFailed.length && !validation.sectionsNeedingReview.length
  && validation.imageCount >= validation.expectedImages && !validation.warnings.some((w) => /placeholder was left|script tag|cut off|larger than/.test(w));

return [{ json: { cleanedHtml: html, validation } }];

// Download Final Report | Mode: Run Once for All Items
// Turns the page into a downloadable .html file (Binary > data) and adds the file name and the validation result.
const input = $input.first().json;
const html = String(input.cleanedHtml || '');
const validation = input.validation || {};
const info = (() => { try { return $('Collect All Sections').first().json; } catch (e) { return {}; } })() || {};
const meta = info.metadata || {};
const category = String(meta.category || 'Rug');
const dateStr = /^\d{4}-\d{2}-\d{2}$/.test(String(meta.isoDate)) ? meta.isoDate : new Date().toISOString().slice(0, 10);
const slug = category.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'rug';
const fileName = `${slug}_trend_report_${dateStr}.html`;

const buffer = Buffer.from(html, 'utf8');
let binaryData;
try {
  binaryData = await this.helpers.prepareBinaryData(buffer, fileName, 'text/html');
} catch (e) {
  binaryData = { data: buffer.toString('base64'), mimeType: 'text/html', fileName };
}

return [{
  json: { fileName, category, validation, sizeKB: Math.round(buffer.length / 1024), generatedAt: new Date().toISOString(), ready: validation.isValid === true },
  binary: { data: binaryData },
}];
